export const manualArt=(mission,page,crop)=>({src:`assets/manual/m${String(mission).padStart(2,'0')}-${page}.jpg`,crop,alt:`Illustrazione originale del manuale, missione ${mission}`});
export const SPIT_REPAIR=manualArt(2,1,[.065,.232,.685,.19]),SPIT_REVEAL=SCENE_ART[2][3],CHILD_PHOTO=manualArt(1,0,[.555,.217,.38,.09]);
