function expand(flat,scope){const list=[];for(let i=0;i<flat.length;i+=2){const art=finaleLineArt(scope,i/2);list.push({character:flat[i],text:flat[i+1],event:'dialogue',id:`${flat[i]}.dialogue.${scope}.${i/2+1}`,...(art!==undefined?{art}:{})});}return list;}
export const introLines=(m,i)=>expand(openings[m][i],`${m}.${i}.intro`),outroLines=(m,i)=>expand(endings[m][i],`${m}.${i}.outro`);
export function pointLines(m,p){const flat=points[`${m}.${p.id}`];if(!flat)throw new Error('Missing dialogue '+m+'.'+p.id);return expand(flat,`${m}.point.${p.id}`);}
export function pointArt(m,p){if(m===10)return FINALE_POINT_ART[p.id]??null;if((m===2&&p.id==='tuning')||(m===4&&p.id==='ready'))return SPIT_REPAIR;if(m===1&&p.id==='photo')return CHILD_PHOTO;return null;}
export const DIALOGUE_VOICES=[...Object.values(MISSIONS).flatMap(m=>m.chapters.flatMap((c,i)=>[...introLines(m.id,i),...outroLines(m.id,i),...(c.points||[]).flatMap(p=>pointLines(m.id,p))])),...pointLines(3,{id:'terminal'}),...pointLines(3,{id:'prototype'})];
